local TobaccoCurer = {}
local PRODUCTS = {
    plain_dried_tobacco = { name = "Navadno sušen tobak", woodCost = 1, linenCost = 1, time = 4, cost = 35, happiness = 2, prestige = 1, description = "Navadno sušen tobak za trgovce." },
    pressed_tobacco_cake = { name = "Stisnjena tobakova pogača", woodCost = 1, linenCost = 1, ironCost = 1, time = 6, cost = 100, happiness = 3, prestige = 2, description = "Stisnjena tobakova pogača za trgovce." },
    silver_box_tobacco = { name = "Srebrna škatlica tobaka", woodCost = 1, silverCost = 1, linenCost = 1, ironCost = 1, time = 9, cost = 280, happiness = 4, prestige = 6, description = "Srebrna škatlica tobaka za plemiče." },
    spiced_tobacco_blend = { name = "Začinjena tobakova mešanica", woodCost = 1, silverCost = 1, spiceCost = 1, linenCost = 1, ironCost = 1, time = 12, cost = 680, happiness = 5, prestige = 14, description = "Začinjena tobakova mešanica za visoke plemiče." },
    gold_lidded_tobacco = { name = "Zlatopokrovka tobakova škatla", woodCost = 1, goldCost = 1, silverCost = 1, spiceCost = 1, linenCost = 1, jewelCost = 1, time = 16, cost = 1500, happiness = 7, prestige = 26, description = "Tobakova škatla z zlatim pokrovom za visoko plemstvo." },
    royal_grand_tobacco_crate = { name = "Kraljevski veliki tobakov zaboj", woodCost = 2, goldCost = 2, silverCost = 2, spiceCost = 2, jewelCost = 2, pearlCost = 1, time = 23, cost = 3500, happiness = 12, prestige = 56, description = "Veliki kraljevski tobakov zaboj z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    tobacco_barn = { name = "Tobakova stodola", cost = { gold = 220, wood = 140, stone = 100, iron = 4 }, upkeep = 5, qualityBonus = 5 },
    curing_loft = { name = "Sušilna podstrešje", cost = { gold = 800, wood = 260, stone = 240, silver = 6, linen = 6 }, upkeep = 18, qualityBonus = 18 },
    master_blender_atelier = { name = "Mojstrski mešalni atelje", cost = { gold = 2300, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 52, qualityBonus = 30 },
    royal_tobacco_palace = { name = "Kraljevska tobakova palača", cost = { gold = 9500, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 50 },
}
TobaccoCurer.woodStock = 16; TobaccoCurer.linenStock = 10; TobaccoCurer.ironStock = 8; TobaccoCurer.spiceStock = 8; TobaccoCurer.silverStock = 6; TobaccoCurer.goldStock = 6; TobaccoCurer.jewelStock = 4; TobaccoCurer.pearlStock = 4
TobaccoCurer.productStock = {}; TobaccoCurer.buildings = {}; TobaccoCurer.maker = nil; TobaccoCurer.activeMaking = {}; TobaccoCurer.totalProducts = 0; TobaccoCurer.dayTimer = 0
function TobaccoCurer.init() TobaccoCurer.woodStock=16; TobaccoCurer.linenStock=10; TobaccoCurer.ironStock=8; TobaccoCurer.spiceStock=8; TobaccoCurer.silverStock=6; TobaccoCurer.goldStock=6; TobaccoCurer.jewelStock=4; TobaccoCurer.pearlStock=4; TobaccoCurer.productStock={}; TobaccoCurer.buildings={}; TobaccoCurer.maker=nil; TobaccoCurer.activeMaking={}; TobaccoCurer.totalProducts=0; TobaccoCurer.dayTimer=0; print("[TobaccoCurer] Royal Tobacco Curer System initialized (6 products, 4 buildings)") end
function TobaccoCurer.hireMaker(n,s) s=s or math.random(55,90); local c=460+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TobaccoCurer.maker={name=n or ("Tobakar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tobakar najet: %s (spretnost: %d)",TobaccoCurer.maker.name,s),"success") end; return true end
function TobaccoCurer.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TobaccoCurer.build(id) local ok,e=TobaccoCurer.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TobaccoCurer.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TobaccoCurer.getQualityBonus() local b=0; for _,bd in ipairs(TobaccoCurer.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TobaccoCurer.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and TobaccoCurer.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.linenCost and TobaccoCurer.linenStock<(d.linenCost or 0) then return false,"Premalo lanu" end; if d.ironCost and TobaccoCurer.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.spiceCost and TobaccoCurer.spiceStock<(d.spiceCost or 0) then return false,"Premalo začimb" end; if d.silverCost and TobaccoCurer.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TobaccoCurer.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TobaccoCurer.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TobaccoCurer.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TobaccoCurer.buildings==0 then return false,"Potrebna tobakova stodola" end; if not TobaccoCurer.maker then return false,"Potreben tobakar" end; return true end
function TobaccoCurer.make(pt,qty) qty=qty or 1; local ok,e=TobaccoCurer.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then TobaccoCurer.woodStock=TobaccoCurer.woodStock-d.woodCost*qty end; if d.linenCost then TobaccoCurer.linenStock=TobaccoCurer.linenStock-d.linenCost*qty end; if d.ironCost then TobaccoCurer.ironStock=TobaccoCurer.ironStock-d.ironCost*qty end; if d.spiceCost then TobaccoCurer.spiceStock=TobaccoCurer.spiceStock-d.spiceCost*qty end; if d.silverCost then TobaccoCurer.silverStock=TobaccoCurer.silverStock-d.silverCost*qty end; if d.goldCost then TobaccoCurer.goldStock=TobaccoCurer.goldStock-d.goldCost*qty end; if d.jewelCost then TobaccoCurer.jewelStock=TobaccoCurer.jewelStock-d.jewelCost*qty end; if d.pearlCost then TobaccoCurer.pearlStock=TobaccoCurer.pearlStock-d.pearlCost*qty end; local t=d.time; if TobaccoCurer.maker then t=math.max(1,t-math.floor(TobaccoCurer.maker.skill/13)) end; table.insert(TobaccoCurer.activeMaking,{id="tobacco_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sušenje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TobaccoCurer.completeMaking(m) local q=1.0+(TobaccoCurer.getQualityBonus()/100); if TobaccoCurer.maker then q=q+(TobaccoCurer.maker.skill/150) end; q=math.min(2.4,q); TobaccoCurer.productStock[m.productType]=(TobaccoCurer.productStock[m.productType] or 0)+m.quantity; TobaccoCurer.totalProducts=TobaccoCurer.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TobaccoCurer.maker then TobaccoCurer.maker.itemsMade=TobaccoCurer.maker.itemsMade+m.quantity; if math.random()<0.25 then TobaccoCurer.maker.skill=math.min(100,TobaccoCurer.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tobak pripravljen: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"tobacco.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function TobaccoCurer.update(dt) if not _G.state then return end; TobaccoCurer.dayTimer=TobaccoCurer.dayTimer+dt; if TobaccoCurer.dayTimer>=30 then TobaccoCurer.dayTimer=0; for i=#TobaccoCurer.activeMaking,1,-1 do local m=TobaccoCurer.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TobaccoCurer.completeMaking(m); table.remove(TobaccoCurer.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TobaccoCurer.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TobaccoCurer.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TobaccoCurer.getStats() return {woodStock=TobaccoCurer.woodStock,linenStock=TobaccoCurer.linenStock,ironStock=TobaccoCurer.ironStock,spiceStock=TobaccoCurer.spiceStock,silverStock=TobaccoCurer.silverStock,goldStock=TobaccoCurer.goldStock,jewelStock=TobaccoCurer.jewelStock,pearlStock=TobaccoCurer.pearlStock,productStock=TobaccoCurer.productStock,numBuildings=#TobaccoCurer.buildings,hasMaker=TobaccoCurer.maker~=nil,makerName=TobaccoCurer.maker and TobaccoCurer.maker.name or "—",makerSkill=TobaccoCurer.maker and TobaccoCurer.maker.skill or 0,activeMaking=#TobaccoCurer.activeMaking,totalProducts=TobaccoCurer.totalProducts} end
return TobaccoCurer
